from collections import defaultdict
import math

MOD = 1_000_000_007

def count_orderings(N, names):
    def factorial(n):
        if n == 0 or n == 1:
            return 1
        else:
            return (n * factorial(n - 1)) % MOD

    def inverse_mod(a, mod=MOD):
        return pow(a, mod - 2, mod)

    prefix_count = defaultdict(int)
    suffix_count = defaultdict(int)

    for name in names:
        prefix_count[name[0]] += 1
        suffix_count[name[-1]] += 1

    total_count = 1
    for prefix, count in prefix_count.items():
        suffix = prefix[::-1]
        if suffix in suffix_count:
            total_count *= factorial(count)
            total_count %= MOD

    return total_count

